/**
 * Domain events fan out into the webhook delivery table, per subscription.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerWebhookListeners } from "@/server/services/webhook-service";
import { webhookEventTypeSchema } from "@/schemas/webhook";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("webhooks", "growth");
  detach = registerWebhookListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("services/webhook-service", () => {
  it("accepts issue.unassigned as a subscribable event type", () => {
    expect(webhookEventTypeSchema.safeParse("issue.unassigned").success).toBe(true);
  });

  // Only enabled endpoints subscribed to issue.unassigned get a delivery.
  it("enqueues one issue.unassigned delivery per subscribed endpoint", async () => {
    const subscribed = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.com/unassigned",
        eventTypes: ["issue.unassigned"],
      },
      "secret-subscribed",
    );
    await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.com/assigned-only",
        eventTypes: ["issue.assigned"],
      },
      "secret-other",
    );

    const payload = {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: tenant.org.createdAt,
      issueId: "iss-webhook-1" as IssueId,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.member,
    };

    await emit("issue.unassigned", payload);

    const deliveries = await webhookRepo.claimPendingDeliveries(100);

    expect(deliveries).toHaveLength(1);
    expect(deliveries[0]).toMatchObject({
      endpointId: subscribed.id,
      eventType: "issue.unassigned",
    });
    expect(JSON.parse(deliveries[0]?.payload ?? "null")).toEqual(payload);
  });
});
EOF
